package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
import java.io.*;import java.net.URI;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.zip.*;
public class VerifiedDependencyPackageTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 byte[] zip(String name,String content)throws Exception {var bytes=new ByteArrayOutputStream();try(var z=new ZipOutputStream(bytes)){z.putNextEntry(new ZipEntry(name));z.write(content.getBytes());z.closeEntry();}return bytes.toByteArray();}
 VerifiedDependencyPackage service(Path root,byte[] bytes,String entry,AtomicInteger downloads)throws Exception {var spec=new VerifiedDependencyPackage.Spec("python","3.13.17",URI.create("https://api.nuget.org/v3-flatcontainer/python/3.13.17/python.3.13.17.nupkg"),VerifiedDependencyPackage.digest(bytes),"tools/",entry,VerifiedDependencyPackage.digest("binary".getBytes()));return new VerifiedDependencyPackage(root,spec,(uri,path,stop)->{downloads.incrementAndGet();Files.write(path,bytes);});}
 @Test public void verifiedCacheReusesGenerationWithoutDownload()throws Exception {Path r=temp.newFolder().toPath();var count=new AtomicInteger();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",count);var a=s.ensure(()->false,x->{});var b=s.ensure(()->false,x->{});assertEquals(a.get("path"),b.get("path"));assertEquals(true,b.get("cache_hit"));assertEquals(1,count.get());assertEquals(true,s.status().get("ready"));}
 @Test public void changedRuntimePreservedAtOriginalPathDuringRepair()throws Exception {Path r=temp.newFolder().toPath();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",new AtomicInteger());Path old=Path.of((String)s.ensure(()->false,x->{}).get("path"));Files.writeString(old,"changed");assertEquals(false,s.status().get("ready"));var repaired=s.ensure(()->false,x->{});assertNotEquals(old.toString(),repaired.get("path"));assertEquals("changed",Files.readString(old));assertEquals(true,s.status().get("ready"));}
 @Test public void extraBytecodeIsRejectedRatherThanIgnored()throws Exception {Path r=temp.newFolder().toPath();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",new AtomicInteger());Path p=Path.of((String)s.ensure(()->false,x->{}).get("path"));Files.writeString(p.resolveSibling("extra.pyc"),"untrusted");assertEquals(false,s.status().get("ready"));}
 @Test public void unsafeZipCannotEscapeEvenWithMatchingArchiveHash()throws Exception {Path r=temp.newFolder().toPath();var s=service(r,zip("tools/../../escape","binary"),"tools/python.exe",new AtomicInteger());try{s.ensure(()->false,x->{});fail();}catch(IOException expected){}assertFalse(Files.exists(r.getParent().resolve("escape")));assertEquals(false,s.status().get("ready"));}
 @Test public void entrypointHashMismatchNeverPublishes()throws Exception {Path r=temp.newFolder().toPath();var s=service(r,zip("tools/python.exe","wrong"),"tools/python.exe",new AtomicInteger());try{s.ensure(()->false,x->{});fail();}catch(IOException expected){}assertFalse(Files.exists(r.resolve("active.json")));}
 @Test public void concurrentRequestsShareOneDownloadAndGeneration()throws Exception {Path r=temp.newFolder().toPath();var count=new AtomicInteger();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",count);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->s.ensure(()->false,x->{}));var b=pool.submit(()->s.ensure(()->false,x->{}));assertEquals(a.get().get("path"),b.get().get("path"));assertEquals(1,count.get());}finally{pool.shutdownNow();}}
 @Test public void cancellationBeforeDownloadDoesNotCreateRoot()throws Exception {Path r=temp.newFolder().toPath().resolve("cache");var count=new AtomicInteger();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",count);try{s.ensure(()->true,x->{});fail();}catch(IOException expected){}assertEquals(0,count.get());assertFalse(Files.exists(r));}
 @Test public void pointerOwnershipChangesArePreserved()throws Exception {Path r=temp.newFolder().toPath();var s=service(r,zip("tools/python.exe","binary"),"tools/python.exe",new AtomicInteger());Files.writeString(r.resolve("active.json"),"{\"owner\":\"someone\",\"generation\":\"../other\"}");try{s.ensure(()->false,x->{});fail();}catch(IOException expected){}assertTrue(Files.readString(r.resolve("active.json")).contains("someone"));}
 @Test public void onlyOfficialHttpsOriginsAndSafePathsAllowed(){for(String u:List.of("http://api.nuget.org/a","https://github.com.evil.test/a","https://user@github.com/a","https://api.nuget.org:444/a"))assertFalse(VerifiedDependencyPackage.allowed(URI.create(u)));for(String p:List.of("../a","tools/../a","/a","C:/a","tools\\a"))assertFalse(VerifiedDependencyPackage.safeName(p));}
 @Test public void bundledPythonDescriptorPinsOfficialStandardX64()throws Exception {var d=VerifiedDependencyPackage.bundled("/resources/test-client/python-runtime.json");assertEquals("python",d.id());assertEquals("3.13.17",d.version());assertEquals("api.nuget.org",d.uri().getHost());assertEquals("tools/python.exe",d.entry());}
}
